import assert from "node:assert/strict";
import { test } from "node:test";
import { retry } from "../src/retry.ts";

test("grader: backoff and give-up", async () => {
  const delays: number[] = [];
  let calls = 0;
  const r = await retry(
    async () => {
      calls++;
      if (calls < 3) throw new Error("flaky");
      return 42;
    },
    { attempts: 5, baseMs: 100, sleep: async (ms) => void delays.push(ms) },
  );
  assert.equal(r, 42);
  assert.deepEqual(delays, [100, 200]);

  const d2: number[] = [];
  let c2 = 0;
  await assert.rejects(
    retry(
      async () => {
        c2++;
        throw new Error(`fail ${c2}`);
      },
      { attempts: 3, baseMs: 10, sleep: async (ms) => void d2.push(ms) },
    ),
    /fail 3/,
  );
  assert.equal(c2, 3);
  assert.deepEqual(d2, [10, 20]);
  await assert.rejects(retry(async () => 1, { attempts: 0, baseMs: 1, sleep: async () => {} }), RangeError);
});

