export interface RetryOptions {
  attempts: number;
  baseMs: number;
  sleep: (ms: number) => Promise<void>;
}

export async function retry<T>(fn: () => Promise<T>, opts: RetryOptions): Promise<T> {
  if (opts.attempts < 1) throw new RangeError("attempts must be at least 1");
  let lastError: unknown;
  for (let n = 1; n <= opts.attempts; n++) {
    try {
      return await fn();
    } catch (e) {
      lastError = e;
      if (n < opts.attempts) await opts.sleep(opts.baseMs * 2 ** (n - 1));
    }
  }
  throw lastError;
}

